      const base = openvirtlist({ surface, total: 0, ...(settings?.virtlistrows !== undefined ? { rows: settings.virtlistrows } : {}) });
      const scrolled = scrollvirtlist({ ...base, total: stored ? Object.keys(stored.heights).length : 0, heights: stored?.heights ?? {} }, input.virtlist.scroll.start ?? 0, settings?.virtlistrows);
