      const chunkbytes = input.stream.windows.chunkbytes ?? 0;
      const windows = streamparsewindows({ bytes, chunkbytes });
      const task = streamparsetaskof({ runid: plan?.id ?? "norun", stepid: "streamparse", chunkbytes, chunks: windows.chunks });
