      await audit("streamparse", `The streamparse yielded ${observations.total} observation${observations.total === 1 ? "" : "s"} progressively across ${chunks.length} chunk${chunks.length === 1 ? "" : "s"} while every chunk passed the same schemastrict validation the one pass parser runs.`, { ...(session ? { sessionid: session.id } : {}), ...(plan ? { planid: plan.id } : {}) });
