    const depths = await memory.getqueuedepths();
    await audit("perf", `The dashboardpage read the perf summary of the run ${runid}: ${records.length} step record${records.length === 1 ? "" : "s"} with the step duration chart, the selcache generation and the worker queue depth.`, { ...(session ? { sessionid: session.id } : {}) });
