    await audit("perf", `The user ${priority} priority ${priority === "speed" ? "defers the heavy capture work to the run end" : "keeps every capture beside its step"}; the choice optimizes the order and never drops a capture.`, { ...(session ? { sessionid: session.id } : {}) });
