      const rebuilt = runfromplan(stored, session?.id ?? "", now);
      await memory.setrunrecord(rebuilt);
      await audit("resume", `The run ${rebuilt.runid} rebuilt from its persisted plan after the service worker restart in the ${rebuilt.state} state; the recovery never bypasses the review.`, { ...(session ? { sessionid: session.id } : {}), planid: rebuilt.planid });
