      if (secret === "") throw new Error("The lazy migration needs its secret through its consent prompt; the key derivation never runs without the user entry.");
      const item = (await memory.getmemoryitems()).find(candidate => candidate.key === key);
      if (item === undefined) throw new Error(`No memory item stands on ${key}.`);
      const derived = await derivekey(secret, `${item.provenance.origin}:${item.provenance.runid}`);
      const migrated = await migrateitem({ item, key: derived, enabled: true });
      await memory.setmemoryitem(migrated);
      await audit("provenance", `The memory item ${key} that predated encryption migrated lazily on first access: its value now encrypts at rest while its provenance stays untouched and the derived key never persists.`, { ...(session ? { sessionid: session.id } : {}), planid: item.provenance.runid });
