    const rules = await memory.getexpiry();
    const steps = plan?.steps ?? [];
    return { items: items.map(item => ({ key: item.key, memoryclass: item.memoryclass, provenance: item.provenance, encrypted: item.encrypted === true, expired: expireditems([item], rules, now).length > 0, stepsummary: stepsummaryfor(item, steps) })) };
