/** The active gateway chat streams: the in-flight states the panel polls through its cursor with their cancel states; a finished stream persists through the memory seam and leaves the map. */
const activegatewaychats = new Map<string, { state: gatewaychatstate; cancel: ReturnType<typeof gatewaycancel> }>();

/** Resolves the key material of one gateway config through the vault seam at the last possible moment: the value reaches the wire header only and never a stored config, an audit entry or a usage record. */
async function gatewaykeyof(config: baseurlconfig): Promise<string | undefined> {
  if (config.keyref === undefined) return undefined;
  const entries = await memory.getsecretvault();
  const entry = entries.find(candidate => candidate.vaultid === config.keyref?.storageid);
  if (entry === undefined) throw new Error(`The provider ${config.providerid} references the stored key ${config.keyref.name} and its vault record is missing; store the key from the options again.`);
  const resolved = await resolveproviderkey({ seam: vaultseamstore, entry });
  if (!resolved.ok || resolved.value === undefined) throw new Error(resolved.reason);
  await memory.stampsecretuse(entry.vaultid, Date.now());
  return resolved.value;
}

/** Reads the gateway state for the panel and the popup: the provider configs with their consent stamps and masked key references, the cached model lists, the chat resolution of the chat task kind, the recent chat exchanges, the token budget with its warning state, the cost estimates per provider and model, the capabilityad preview and the prompt templates of the family — the state carries no key material anywhere. */
